DESC = "ElevenLabs Bella take (external)"
PARAS = [
    ("Movie villains can't use iPhones. Knives Out director Rian Johnson let it slip in twenty twenty. Apple lets films use iPhones. But, quote, bad guys cannot have iPhones on camera. So why would Apple care what a villain holds? Because a movie is an ad you can't skip. Every hero with an iPhone tells you who the good guys are. Apple has never confirmed it. But now you'll check every villain's phone. Send this to your movie night crew.", 0.0, 1),
]
